import { THREE_DS_GAMES, type ThreeDsGame, type ThreeDsGameName } from "../games";

/**
 * The tables one 3DS game needs, loaded when its mapper is detected (`prepare(game)` in `games/gen6/index.ts`): each
 * Pokedex is 2.4-3.2 MB of source, so only the detected game's is fetched, each table in its own lazy chunk.
 *
 * Everything under `data/` except `style/`, `textures.ts` and this file is generated by `tools/gen6/build-data.mjs`
 * from the shared pokemon-data repo, in the shapes gen5's tables have (ARCHITECTURE §6).
 */

export interface DexEntry {
    species: string;
    national_dex_number: number;
    base_stats: Record<"hp" | "attack" | "defense" | "special_attack" | "special_defense" | "speed", number>;
    type_1: string;
    type_2: string;
    growth_rate: string;
    abilities: string[];
    hidden_ability: string | null;
    level_up_learnset: [number, string][];
    tm_hm_learnset: string[];
    tutor_learnset?: string[];
    weight?: number;
    evolution_family?: { species: string; method: string | null; parameter: unknown }[];
    [field: string]: unknown;
}

export interface MoveEntry {
    rom_id: number;
    move: string;
    type: string;
    category: "Physical" | "Special" | "Status";
    pp: number | null;
    power: number | null;
    accuracy: number | null;
    priority: number;
    [field: string]: unknown;
}

export interface GameData {
    game: ThreeDsGame;
    pokedex: Record<string, DexEntry>;
    moves: Record<string, MoveEntry>;
    /** "TM01" -> move. */
    tmhm: Record<string, string>;
    /** Move -> "TM01". */
    machineOf: Record<string, string>;
    /** Attacking type -> defending type -> multiplier. */
    typeChart: Record<string, Record<string, number>>;
    /** Scott's run rules: "Banned", "First Playthrough" and the game's own list. */
    unobtainable: Record<string, string[]>;
    /** Species or form -> picture path. */
    speciesArt: Record<string, string>;
}

const DEX_LOADERS: Record<ThreeDsGameName, () => Promise<{ pokedex: Record<string, DexEntry> }>> = {
    "X and Y": () => import("./pokedex/x_y.js") as any,
    "Omega Ruby and Alpha Sapphire": () => import("./pokedex/omega_ruby_alpha_sapphire.js") as any,
    "Sun and Moon": () => import("./pokedex/sun_moon.js") as any,
    "Ultra Sun and Ultra Moon": () => import("./pokedex/ultra_sun_ultra_moon.js") as any,
};

const loaded = new Map<ThreeDsGameName, Promise<GameData>>();
let current: GameData | null = null;

async function load(name: ThreeDsGameName): Promise<GameData> {
    const game = THREE_DS_GAMES[name];
    const [dex, moves, tmhm, chart, rules, art] = await Promise.all([
        DEX_LOADERS[name](),
        (game.generation === 6 ? import("./moves_gen6.js") : import("./moves_gen7.js")) as unknown as Promise<{ moves: Record<string, MoveEntry> }>,
        import("./tmhm.js") as unknown as Promise<{ tmhm: Record<string, Record<string, string>> }>,
        import("./type_chart.js") as unknown as Promise<{ typeChart: Record<string, Record<string, number>> }>,
        import("./unobtainable_moves.js") as unknown as Promise<{ unobtainable_moves_object: Record<string, string[]> }>,
        import("./species_art.js") as unknown as Promise<{ speciesArt: Record<string, string> }>,
    ]);
    const machines = tmhm.tmhm[name] ?? {};
    const machineOf: Record<string, string> = {};
    for (const [machine, move] of Object.entries(machines)) machineOf[move] ??= machine;
    return {
        game,
        pokedex: dex.pokedex,
        moves: moves.moves,
        tmhm: machines,
        machineOf,
        typeChart: chart.typeChart,
        unobtainable: rules.unobtainable_moves_object,
        speciesArt: art.speciesArt,
    };
}

/** Loads the game's tables (once) and makes them the current ones. An unknown game loads X/Y's. */
export async function loadGameData(game: string | undefined): Promise<GameData> {
    const name = (game && game in THREE_DS_GAMES ? game : "X and Y") as ThreeDsGameName;
    let pending = loaded.get(name);
    if (!pending) {
        pending = load(name);
        loaded.set(name, pending);
    }
    current = await pending;
    return current;
}

/** The detected game's tables. Throws before `loadGameData` has run: the module's `prepare` awaits it. */
export function gameData(): GameData {
    if (!current) throw new Error("the 3DS game data is not loaded; the module's prepare() must run first");
    return current;
}
